"""CPU-only probability-runtime identity; importing this module imports no ML stack."""
from __future__ import annotations

import hashlib
import importlib
import json
import platform
from pathlib import Path

SCHEMA = "flash-probability-runtime-v1"


def digest(value):
    return hashlib.sha256(json.dumps(value, sort_keys=True, separators=(",", ":"),
                                     allow_nan=False).encode()).hexdigest()


def source_identity(path):
    """Hash actual resolved code, excluding generated bytecode, never distribution metadata.

    Absolute installation paths are excluded: identical code can be relocated.
    Directories bind all non-cache files, including native kernels and config assets.
    """
    root = Path(path).resolve(strict=True)
    files = [root] if root.is_file() else sorted(
        p for p in root.rglob("*") if p.is_file()
        and "__pycache__" not in p.relative_to(root).parts
        and p.suffix not in (".pyc", ".pyo"))
    if not files:
        raise ValueError(f"Empty implementation source: {root}")
    entries = []
    for file in files:
        h = hashlib.sha256()
        with file.open("rb") as stream:
            for block in iter(lambda: stream.read(1024 * 1024), b""):
                h.update(block)
        entries.append({"file": file.name if root.is_file() else file.relative_to(root).as_posix(),
                        "sha256": h.hexdigest()})
    return {"files": entries, "sha256": digest(entries)}


def collect_runtime(*, fla_active, active_sources=None, importer=importlib.import_module):
    """Capture runtime in the SAME interpreter that computes log probabilities.

    active_sources maps each enabled implementation component name (e.g.
    humming.expert_forward/qsa.kernel) to ONE explicit source file; directories
    are rejected so adjacent probe outputs cannot enter the identity.
    Caller must pass all enabled candidates and their implementation dependencies;
    missing files fail closed. No CUDA device/driver queries or allocation occur.
    FLA resolves through Python imports so PYTHONPATH overlays are fingerprinted.
    """
    modules = {name: importer(name) for name in ("torch", "triton", "transformers")}
    dependencies = {}
    for name, module in modules.items():
        version = getattr(module, "__version__", None)
        origin = getattr(module, "__file__", None)
        if not version or not origin:
            raise ValueError(f"Unidentifiable dependency: {name}")
        dependencies[name] = {"version": str(version), "source": source_identity(origin)}
    torch = modules["torch"]
    cuda = getattr(torch.version, "cuda", None)
    if not cuda:
        raise ValueError("CUDA build identity is required for this GPU probability runtime")
    implementations = {}
    if fla_active:
        fla = importer("fla")
        operation = importer("fla.ops.gated_delta_rule")
        roots = list(getattr(fla, "__path__", ()))
        if not roots or not getattr(operation, "__file__", None):
            raise ValueError("Cannot resolve active FLA implementation")
        implementations["fla"] = {"roots": sorted((source_identity(p) for p in roots), key=digest),
                                   "resolved_operation": source_identity(operation.__file__)}
    for name, source in sorted((active_sources or {}).items()):
        if not isinstance(name, str) or not name or name == "fla":
            raise ValueError("Candidate names must be nonempty and not shadow FLA")
        source = Path(source).resolve(strict=True)
        if not source.is_file():
            raise ValueError(f"Candidate source must be an explicit implementation file: {name}")
        implementations[name] = source_identity(source)
    return {"schema": SCHEMA, "identity_helper": source_identity(__file__),
            "python": {"version": platform.python_version(), "implementation": platform.python_implementation()},
            "dependencies": dependencies,
            "cuda_build": str(cuda), "torch_git": getattr(torch.version, "git_version", None),
            "math": {"float32_matmul_precision": torch.get_float32_matmul_precision(),
                     "cuda_matmul_allow_tf32": bool(torch.backends.cuda.matmul.allow_tf32),
                     "cudnn_allow_tf32": bool(torch.backends.cudnn.allow_tf32),
                     "deterministic_algorithms": bool(torch.are_deterministic_algorithms_enabled())},
            "fla_active": bool(fla_active), "implementations": implementations}


def bind_profile(base_profile, runtime):
    if runtime.get("schema") != SCHEMA:
        raise ValueError("Missing or unsupported probability runtime schema")
    return {**base_profile, "runtime_identity": runtime, "runtime_identity_sha256": digest(runtime)}


def require_matching_profile(artifact, current_profile):
    """Require both full profile and its digest; legacy hash-optional caches fail closed."""
    runtime = current_profile.get("runtime_identity", {})
    if runtime.get("schema") != SCHEMA or current_profile.get("runtime_identity_sha256") != digest(runtime):
        raise ValueError("Current probability runtime identity is missing or corrupt")
    if artifact.get("probability_profile") != current_profile:
        raise ValueError("Stale or missing artifact probability runtime/profile")
    if artifact.get("probability_profile_sha256") != digest(current_profile):
        raise ValueError("Stale or missing artifact probability profile digest")
